function tacticalSpriteMarkup(id,facing=0){
 const index=TacticalBattle.sprites.findIndex(s=>s.id===id);if(index<0)return '';
 const [x,y,w,h,clip]=tacticalSpriteFrames[index],key='mercenary-clip-'+(++tacticalSpriteSequence);
 return `<svg class="mercenary-sprite" viewBox="${x} ${y} ${w} ${h}" style="--sprite-angle:${(Number.isInteger(facing)?facing:0)*45}deg" aria-hidden="true" focusable="false"><defs><clipPath id="${key}">${clip?`<path d="${clip}"></path>`:`<rect x="${x}" y="${y}" width="${w}" height="${h}"></rect>`}</clipPath></defs><image href="assets/mercenaries-v1.png" width="1536" height="1024" clip-path="url(#${key})"></image></svg>`;
}
function tacticalSpritePicker(selected,action='pick-sprite'){
 return `<div class="tactical-sprite-picker" role="group" aria-label="Выбор спрайта">${[{id:'',name:'Инициалы'},...TacticalBattle.sprites].map(s=>`<button type="button" data-tactical="${action}" data-sprite="${s.id}" aria-pressed="${(selected||'')===s.id}">${tacticalSpriteMarkup(s.id)||'<span class="sprite-initials-preview" aria-hidden="true">АБ</span>'}<span>${esc(s.name)}</span></button>`).join('')}</div>`;
}
playPages.splice(2,0,['Тактика',9]);
function tacticalSelf(){return tacticalDemo?'demo':cloudUser?.uid;}
function tacticalOwner(){return tacticalDemo||tacticalRoom?.ownerUid===cloudUser?.uid;}
function tacticalCanControl(unit){return tacticalState&&TacticalBattle.owns(tacticalState,tacticalSelf(),unit,tacticalRoom?.ownerUid||'demo');}
function tacticalTeam(){return tacticalState?.teams.find(t=>t.ownerUid===tacticalSelf());}
function tacticalPlayerName(){return cloudUser?.displayName||cloudUser?.email?.split('@')[0]||'Игрок';}
function tacticalNumber(value,fallback){const n=Number.parseFloat(value);return Number.isFinite(n)?n:fallback;}
function tacticalSnapshot(record){
 const previous=state;
 try{
  prepareCharacter(record.data);if(state.play.rules){state.play.rules.stance=null;state.play.rules.flurry=false;}migrateEffects();refreshEffectAp();syncMaxHp();const movement=movementValues();
  const weapons=state.items.filter(i=>i.category==='Оружие'&&i.equipped).slice(0,8).map(item=>({item,a:attackNumbers(item)}));
  const melee=meleeSkills();if(melee.length&&!weapons.some(w=>w.a.key?.startsWith('Ближний бой'))&&weapons.length<8){const skill=melee[0],item={name:'Безоружный удар',category:'Оружие',equipped:true,details:{skill:skillIdentity(skill),type:combatKey(skill),bareFist:true,damage:abilityState().meleeBase.damage||'1d100',actionCost:String(abilityState().meleeBase.cost||6),range:'1',armorPen:'0'}};weapons.push({item,a:attackNumbers(item)});}
  const attacks=weapons.map(({item,a})=>{const ammo=attackAmmo(item);return {name:item.name,cost:Math.max(1,a.cost||6),chance:a.chance??50,damage:a.damage,bb:a.bb??0,range:Math.max(1,tacticalNumber(a.range,1)),ammo:ammo.cost?ammo.current:null,ammoCost:ammo.cost,melee:!!a.key?.startsWith('Ближний бой'),level:a.level||0,baseStat:statTotal(a.key?.includes('силовой')?'STR':a.key?.startsWith('Ближний бой')?'DEX':a.key==='Стрельба(энергия)'?'INT':'ACC'),criticalChance:Math.max(0,a.criticalChance||0),criticalPower:a.criticalPowerBonus||0,criticalMultiplier:a.criticalMultiplierBonus||0,hand:/двуруч/i.test(item.details?.type||item.notes||'')?'both':item.details?.hand||'right'};});
  const moves=weapons.flatMap(({item,a},attackIndex)=>a.key?.startsWith('Ближний бой')?learnedMoves().map(entry=>{const m=meleeMoveNumbers(entry,a.skill,item,a.cost);return {name:entry.title,attackIndex,level:a.level,cost:m.cost,chance:m.chance,defense:m.defense,blocked:moveRequirements(entry).join(', ')};}):[]).slice(0,64);
  const derived=derivedPlay(),strong=melee.filter(s=>combatKey(s)?.includes('силовой')),opportunityMax=strong.length?Math.max(...strong.map(s=>Math.max(0,Math.min(10,effectiveSkillLevel(s))-4))):0;
  return TacticalBattle.sanitizeUnit({name:state.info.name,sourceId:record.id,spriteId:TacticalBattle.sprites.some(s=>s.id===state.info.tacticalSprite)?state.info.tacticalSprite:null,facing:0,hpMax:state.info.maxhp,hp:state.info.hp,apMax:Math.max(1,state.play.apMax),walk:movement.walk||1,run:movement.run||2,jump:movement.jump||0,jumpCost:movement.jumpCost||2,reaction:derived.initiative,armor:resolveEffectTarget(state.zones[1].armor||0,'armor').value,firstTurn:!!abilitySource('Первый ход'),attacks,moves,stats:Object.fromEntries(['STR','DEX','CON','RTC','ACC','INT','LCK'].map(k=>[k,statTotal(k)])),dodge:Math.max(0,derived.dodge),defenseLevel:melee.length?Math.max(...melee.map(effectiveSkillLevel)):0,shock:Math.max(0,derived.shock||0),painThresholdDisabled:!!abilitySource('Отключение болевого порога'),critImmune:!!abilitySource('Иммунитет к критическим попаданиям'),heavyRegen:!!state.info.heavyRegen,zones:state.zones.map(z=>({armor:resolveEffectTarget(z.armor||0,'armor').value,damage:z.damage||0,tier:injuryFor(state.zones.indexOf(z),z.damage||0).tier||0})),opportunityMax});
 }finally{state=previous;applyUiScales();}
}
function tacticalDefaultUnit(){return {name:'Новый боец',hpMax:100,hp:100,apMax:10,walk:1,run:2,jump:4,jumpCost:2,reaction:10,armor:0,dodge:10,shock:10,defenseLevel:1,opportunityMax:0,stats:{STR:10,DEX:10,CON:10,RTC:10,ACC:10,INT:10,LCK:0},attacks:[{name:'Атака',cost:6,chance:50,damage:'1d100',bb:0,range:6,ammo:12,ammoCost:1}]};}
function tacticalReport(message,error=false){tacticalStatus=message;document.querySelectorAll('[data-tactical-status]').forEach(el=>{el.textContent=message;el.classList.toggle('cloud-error',error);});}
function tacticalRefresh(){
 if(page!==9||libraryHome)return;if(document.querySelector('dialog[open]'))return;
 const board=document.querySelector('.tactical-map-scroll'),scroll=board?{x:board.scrollLeft,y:board.scrollTop}:null;render();const next=document.querySelector('.tactical-map-scroll');if(next&&scroll){next.scrollLeft=scroll.x;next.scrollTop=scroll.y;}
}
function tacticalDisconnect(){tacticalClient?.disconnect();tacticalClient=null;tacticalState=null;tacticalRoom=null;tacticalCode='';tacticalMembers=[];tacticalSelected='';tacticalPending=false;tacticalDemo=false;tacticalBrush='';tacticalMode='walk';tacticalAttack=0;tacticalSelectedMove=null;tacticalLocalSetup=null;}
function tacticalRoomClient(){
 if(!cloudUser||!cloudApi?.fs||cloudSwitching)throw Error('Войдите через Google, чтобы играть онлайн.');
 const uid=cloudUser.uid;return new BattleRoomClient({fs:cloudApi.fs,db:cloudDb,uid,displayName:tacticalPlayerName(),
  onState:(battle,room,code)=>{if(cloudUser?.uid!==uid)return;tacticalState=battle;tacticalRoom=room;tacticalCode=code;tacticalDemo=false;if(!battle.units.some(u=>u.id===tacticalSelected))tacticalSelected=battle.units.find(u=>tacticalCanControl(u))?.id||battle.units[0]?.id||'';try{localStorage.setItem('tactical-room:'+uid,code);}catch{}tacticalRefresh();},
  onMembers:members=>{if(cloudUser?.uid===uid){tacticalMembers=members;tacticalRefresh();}},
  onStatus:(text,error)=>{if(cloudUser?.uid===uid)tacticalReport(text,error);},
  onResult:(status,message)=>{if(cloudUser?.uid!==uid)return;tacticalPending=false;tacticalReport(status==='rejected'?message:'Действие подтверждено',status==='rejected');if(status==='rejected')toast(message);tacticalRefresh();}
 });
}
async function tacticalConnect(create=false){
 const code=document.querySelector('#tactical-code')?.value||tacticalInvitation,team=document.querySelector('#tactical-team-name')?.value||'Команда '+tacticalPlayerName(),map=document.querySelector('#tactical-new-map')?.value||'ruins';
 tacticalDisconnect();const client=tacticalRoomClient();tacticalClient=client;tacticalPending=true;tacticalReport('Подключаем комнату…');
 try{tacticalCode=create?await client.create(team,map):await client.join(code,team);tacticalDialog=null;tacticalReport('Подключено');}
 catch(error){tacticalReport(client.message(error),true);client.disconnect();tacticalClient=null;throw error;}
 finally{tacticalPending=false;tacticalRefresh();}
}
async function tacticalSend(kind,payload={}){
 if(tacticalPending)throw Error('Дождитесь подтверждения предыдущего действия.');
 if(tacticalDemo){const setup=kind==='start'?structuredClone(tacticalState):null;tacticalState=TacticalBattle.apply(tacticalState,{kind,payload},'demo','demo',()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296);if(setup)tacticalLocalSetup=setup;if(['start','endTurn','undo'].includes(kind)){const team=TacticalBattle.activeTeam(tacticalState);tacticalSelected=tacticalState.units.find(u=>u.teamId===team?.id&&u.hp>0)?.id||tacticalSelected;tacticalMode='walk';}tacticalDialog=null;tacticalRefresh();return;}
 if(!tacticalClient)throw Error('Сначала подключитесь к комнате.');tacticalPending=true;tacticalReport('Ожидаем подтверждения ведущего…');tacticalRefresh();
 try{await tacticalClient.submit(kind,payload);}catch(error){tacticalPending=false;tacticalReport(tacticalClient.message(error),true);tacticalRefresh();throw error;}
}
function tacticalDemoBattle(){
 tacticalDisconnect();tacticalDemo=true;tacticalRoom={ownerUid:'demo'};let b=TacticalBattle.create('demo','Разведчики','ruins');b=TacticalBattle.apply(b,{kind:'team',payload:{name:'Рейдеры'}},'demo','demo');b=TacticalBattle.apply(b,{kind:'team',payload:{name:'Охрана'}},'demo','demo');
 for(const [ti,team] of b.teams.entries())for(let n=0;n<2;n++){const unit=tacticalDefaultUnit();unit.name=['Разведчик','Рейдер','Страж'][ti]+' '+(n+1);unit.reaction=15-ti*3;unit.hp=unit.hpMax=160;unit.attacks[0]={...unit.attacks[0],name:'Карабин',cost:4,chance:70,damage:'2d20 + 10',range:12};b=TacticalBattle.apply(b,{kind:'addUnit',payload:{teamId:team.id,unit}},'demo','demo');}
 tacticalState=b;tacticalSelected=b.units[0].id;tacticalStatus='Демо: ведущий управляет всеми командами.';tacticalRefresh();
}
function tacticalSoloBattle(characterId='',map='arena',enemyCount=1){
 const record=characterRecords.find(r=>r.id===characterId&&!r.deletedAt);
 if(characterId&&!record)throw Error('Персонаж недоступен. Выберите другого.');
 if(!Number.isInteger(enemyCount)||enemyCount<1||enemyCount>3)throw Error('Выберите от 1 до 3 противников.');
 const unit=record?tacticalSnapshot(record.id===activeCharacterId?{...record,data:structuredClone(state)}:record):tacticalDefaultUnit();
 if(!record)unit.name='Тренировочный боец';
 if(unit.hp<=0)throw Error('У персонажа нет HP. Восстановите HP в листе или выберите тренировочного бойца.');
 // Training weapons exist only in this detached copy and are not Sacralic equipment.
 const training=!unit.attacks.length;
 if(training)unit.attacks=[{name:'Учебная атака',cost:Math.min(6,unit.apMax),chance:70,damage:'1d20 + 5',bb:0,range:6,ammo:12,ammoCost:1}];
 let b=TacticalBattle.create('demo','Моя команда',map);
 const apply=(kind,payload)=>{b=TacticalBattle.apply(b,{kind,payload},'demo','demo');};
 apply('team',{name:'Противники'});apply('addUnit',{teamId:b.teams[0].id,unit});
 for(let i=0;i<enemyCount;i++){const enemy=tacticalDefaultUnit();enemy.name='Противник '+(i+1);enemy.spriteId=TacticalBattle.sprites[[2,3,5][i]].id;enemy.reaction=5;enemy.attacks=[{name:'Учебный карабин',cost:4,chance:60,damage:'1d20 + 5',bb:0,range:12,ammo:12,ammoCost:1}];apply('addUnit',{teamId:b.teams[1].id,unit:enemy});}
 // A clear row exists in every preset, keeping both melee and ranged tests close.
 for(const [i,fighter] of b.units.entries())apply('deploy',{unitId:fighter.id,x:i===0?3:6+i,y:5});
 b.history=[];
 tacticalDisconnect();tacticalDemo=true;tacticalRoom={ownerUid:'demo'};tacticalState=b;tacticalLocalSetup=structuredClone(b);tacticalSelected=b.units[0].id;
 tacticalStatus='Локальный тест: вы управляете обеими командами. Расставьте бойцов и нажмите «Начать бой».'+(training?' У персонажа нет оружия: добавлена учебная атака только для этого боя.':'');tacticalRefresh();
}
function tacticalResetLocal(){
 if(!tacticalDemo||!tacticalLocalSetup)throw Error('Нет начальной расстановки.');
 tacticalState=structuredClone(tacticalLocalSetup);tacticalSelected=tacticalState.units[0]?.id||'';tacticalMode='walk';tacticalBrush='';tacticalAttack=0;tacticalDialog=null;tacticalStatus='Начальная расстановка восстановлена. HP, ОД и боезапас сброшены.';tacticalRefresh();
}
function tacticalLocationOptions(selected='ruins'){return Object.entries(TacticalBattle.locations).map(([key,m])=>`<option value="${key}" ${key===selected?'selected':''}>${m.name}</option>`).join('');}
function renderTacticalEntry(){
 let last='';try{last=cloudUser?localStorage.getItem('tactical-room:'+cloudUser.uid)||'':'';}catch{}
 const records=characterRecords.filter(r=>!r.deletedAt),selected=records.find(r=>r.id===activeCharacterId)?.id||records[0]?.id||'';
 return `<section class="battle-card tactical-entry"><div class="tag">SACRALIC / TACTICS</div><h1>Тактический бой</h1><section class="tactical-solo-entry"><div class="tag">БЕЗ ВХОДА И ДРУЗЕЙ</div><h2>Тестировать одному</h2><p>Ваш персонаж против готовых противников. Обеими командами управляете вы, по очереди.</p><div class="tactical-solo-fields"><label>Персонаж<select id="tactical-solo-character">${records.map(r=>`<option value="${esc(r.id)}" ${r.id===selected?'selected':''}>${esc(r.data.info.name)}</option>`).join('')}<option value="" ${!selected?'selected':''}>Тренировочный боец</option></select></label><label>Готовая локация<select id="tactical-solo-map">${tacticalLocationOptions('arena')}</select></label><label>Противники<select id="tactical-solo-enemies"><option value="1">1 противник</option><option value="2">2 противника</option><option value="3">3 противника</option></select></label></div><button class="primary-action" data-tactical="solo">Создать тестовый бой</button><small>Листы персонажей не меняются. Тест хранится в этой вкладке до её закрытия или перезагрузки.</small></section><h2 class="tactical-online-heading">Играть онлайн</h2><div class="tactical-entry-grid"><div><h3>Создать сражение</h3><label>Ваша команда<input id="tactical-team-name" maxlength="50" value="Команда ${esc(tacticalPlayerName())}"></label><label>Локация<select id="tactical-new-map">${tacticalLocationOptions()}</select></label><button data-tactical="create" ${!cloudUser||tacticalPending?'disabled':''}>Создать комнату</button></div><div><h3>Присоединиться</h3><label>Код комнаты<input id="tactical-code" maxlength="12" autocomplete="off" autocapitalize="characters" placeholder="ABCD2345" value="${esc(tacticalInvitation||last)}"></label><button data-tactical="join" ${!cloudUser||tacticalPending?'disabled':''}>Войти в комнату</button>${!cloudUser?'<button data-cloud="login">Войти через Google</button>':''}<button data-tactical="demo">Пример боя · 3 команды</button></div></div><p data-tactical-status role="status">${esc(tacticalStatus)}</p><details><summary>Как устроен бой</summary>${tacticalHelp()}</details></section>`;
}
function tacticalHelp(){return '<div class="tactical-help"><p>В локальном тесте вход не нужен: вы управляете всеми командами. Выберите персонажа, готовую локацию и число противников; перед стартом можно добавлять бойцов в любую команду и менять расстановку. После завершения хода выбирается боец следующей команды. «Заново» возвращает расстановку перед последним стартом, HP, ОД и боезапас. Учебные противники и учебная атака служат для тестов, а не задают правила Sacralic.</p><p>До 8 команд, по 8 бойцов. Каждый игрок управляет своей командой; ведущий выбирает карту, добавляет команды NPC и запускает бой. Ведущий должен держать комнату открытой: он подтверждает действия игроков.</p><p>Команды ходят по очереди, порядок определяется максимальной реакцией в команде. ОД каждого бойца восстанавливаются в начале нового раунда. На карте одна клетка равна одному метру. Движение — по восьми направлениям без прохода через углы стен. Трудная местность считается за две клетки.</p><p>Атака проверяет дальность, прямую видимость и d100 против шанса. Укрытие снижает шанс на 20 п.п. Поглощение брони = (AR − AB) × 10%, от 0 до 100%. Расход ОД и патронов применяется даже при промахе; боезапас может стать отрицательным. Атаки, защитные броски, криты, d6 зоны попадания, броня, травмы и стойкость считаются автоматически и подробно записываются в журнал. Силовые поля и нестандартная анатомия требуют решения ведущего; HP можно поправить вручную.</p><p>Силовой стиль получает S−4 зарядов атаки по возможности начиная с навыка 5. Заряды восстанавливаются в начале собственного хода. За один ход команды нельзя повторно атаковать того же противника. При движении в радиусе ближнего оружия бой останавливается до решения владельца: бесплатная атака или пропуск. Порядок d6: 1 — левая нога, 2 — правая нога, 3 — тело, 4 — голова, 5 — левая рука, 6 — правая рука.</p><p>Бойцы в комнате — копии листов. Боевые HP и боезапас не перезаписывают исходных персонажей. Код комнаты служит приглашением; не публикуйте его, если не хотите новых участников.</p></div>';}
function renderTacticalMap(){
 const b=tacticalState,unit=b.units.find(u=>u.id===tacticalSelected),canMove=unit&&tacticalCanControl(unit)&&TacticalBattle.combat.canAct(unit,b)&&!b.pendingMove&&b.phase==='battle'&&TacticalBattle.activeTeam(b)?.id===unit.teamId;
 let reach=null;if(canMove&&tacticalMode!=='attack'&&tacticalMode!=='jump')reach=TacticalBattle.paths(b,unit).dist;
 return `<div class="tactical-map-scroll" tabindex="0" aria-label="Карта боя, можно прокручивать"><div class="tactical-map theme-${b.map.key}" style="--battle-cols:${b.map.w};--battle-cell:${tacticalZoom}px" role="group" aria-label="${esc(b.map.name)}">${Array.from({length:b.map.w*b.map.h},(_,i)=>{const x=i%b.map.w,y=Math.floor(i/b.map.w),terrain=b.map.tiles[i],token=b.units.find(u=>u.x===x&&u.y===y),team=token&&b.teams.find(t=>t.id===token.teamId);let cost=null;if(canMove&&!token&&terrain!=='#'&&tacticalMode!=='attack'){if(tacticalMode==='jump'){if(TacticalBattle.distance(unit,{x,y})<=TacticalBattle.combat.speed(unit,b,'jump')&&TacticalBattle.lineOfSight(b,unit,{x,y}))cost=unit.jumpCost;}else{const steps=reach?.get(i);if(steps!==undefined)cost=Math.max(1,Math.ceil(steps/Math.max(.01,TacticalBattle.combat.speed(unit,b,tacticalMode))));}}const reachable=cost!==null&&cost<=unit.ap;return `<button class="battle-cell terrain-${terrain==='#'?'wall':terrain==='~'?'rough':terrain==='c'?'cover':'floor'} ${token?.id===tacticalSelected?'selected':''} ${token?.hp===0?'down':''} ${reachable?'reachable':''}" data-tactical="cell" data-x="${x}" data-y="${y}" aria-label="Клетка ${x+1}:${y+1}${token?' · '+esc(token.name)+' · '+token.hp+' HP':terrain==='#'?' · стена':terrain==='~'?' · трудная местность':terrain==='c'?' · укрытие':''}${reachable?' · '+cost+' ОД':''}">${token?`<span class="battle-token ${token.spriteId?'has-sprite':''}" style="--team-color:${team.color}">${tacticalSpriteMarkup(token.spriteId,token.facing)||esc(token.name.split(/\s/).map(w=>w[0]).join('').slice(0,2))}</span><span class="battle-token-hp" style="--health:${Math.round(token.hp/token.hpMax*100)}%"></span>`:terrain==='#'?'<span aria-hidden="true">▰</span>':terrain==='c'?'<span aria-hidden="true">▱</span>':reachable?`<small>${cost}</small>`:''}</button>`;}).join('')}</div></div>`;
}
function renderTacticalMoves(u,turn){
 return (u.moves||[]).length?`<section class="tactical-learned-moves"><h3>Приёмы ближнего боя</h3>${u.moves.map((m,i)=>{const weapon=u.attacks[m.attackIndex],a=TacticalBattle.combat.attackValues(u,weapon,tacticalState,m);return `<div><button data-tactical="select-move" data-move="${i}" aria-pressed="${tacticalSelectedMove===i&&tacticalMode==='attack'}" ${!turn||tacticalPending||a.cost!==null&&u.ap<a.cost||m.blocked&&!tacticalOwner()?'disabled':''}><b>${esc(m.name)}</b><strong>${/стойка$/.test(m.name)?'d6':a.chance===null?'—':a.chance+'%'}</strong><small>${a.cost??'Цена мастера'} ОД · ${esc(weapon.name)} · ${weapon.range} кл.</small></button><button class="info-dot" data-tactical="move-info" data-move="${i}" aria-label="Описание приёма ${esc(m.name)}">i</button></div>`;}).join('')}</section>`:'';
}
function renderTacticalReactions(){
 const b=tacticalState;if(!b.pendingMove)return '';return `<section class="battle-card tactical-reactions" aria-label="Атаки по возможности"><h2>Атаки по возможности</h2>${b.reactions.map(r=>{const u=b.units.find(u=>u.id===r.unitId),target=b.units.find(u=>u.id===r.targetId),a=u.attacks[r.attackIndex],owned=tacticalCanControl(u);return `<article><b>${esc(u.name)} → ${esc(target.name)}</b><span>${esc(a.name)} · радиус ${a.range} · заряды ${u.opportunityLeft}/${u.opportunityMax}</span><button data-tactical="opportunity" data-reaction="${r.id}" ${!owned||tacticalPending?'disabled':''}>Атаковать бесплатно</button><button data-tactical="skip-opportunity" data-reaction="${r.id}" ${!owned||tacticalPending?'disabled':''}>Пропустить</button>${!owned?'<small>Ожидаем решение владельца бойца.</small>':''}</article>`;}).join('')}</section>`;
}
function renderTacticalUnit(){
 const b=tacticalState,u=b.units.find(v=>v.id===tacticalSelected);if(!u)return '<p class="muted">Выберите бойца на карте или в списке команды.</p>';
 const owned=tacticalCanControl(u),turn=b.phase==='battle'&&TacticalBattle.activeTeam(b)?.id===u.teamId&&owned&&TacticalBattle.combat.canAct(u,b)&&!b.pendingMove,team=b.teams.find(t=>t.id===u.teamId);
 return `<div class="tactical-unit-head">${tacticalSpriteMarkup(u.spriteId,u.facing)}<span class="tactical-team-dot" style="background:${team.color}"></span><h2>${esc(u.name)}</h2><small>${esc(team.name)}</small></div><div class="play-summary">${metric('HP',u.hp+' / '+u.hpMax)}${metric('ОД',u.ap+' / '+TacticalBattle.combat.apMax(u,b))}${metric('Шаг / бег',TacticalBattle.combat.speed(u,b,'walk')+' / '+TacticalBattle.combat.speed(u,b,'run'))}${metric('Броня / реакция',u.armor+' / '+u.reaction)}</div>${owned&&u.sourceId&&characterRecords.some(r=>r.id===u.sourceId&&!r.deletedAt)&&['lobby','paused'].includes(b.phase)?`<button data-tactical="refresh-sheet" data-unit="${u.id}">Обновить из листа</button>`:''}${owned?`<div class="tactical-appearance-controls"><button data-tactical="unit-sprite" data-unit="${u.id}">Изменить спрайт</button><button data-tactical="face" data-delta="-1" aria-label="Повернуть бойца влево">↶</button><button data-tactical="face" data-delta="1" aria-label="Повернуть бойца вправо">↷</button></div>`:''}${b.phase==='lobby'&&owned?`<p class="muted">Нажмите свободную клетку, чтобы расставить бойца.</p><button data-tactical="remove-unit" data-unit="${u.id}">Убрать из команды</button>`:''}${turn?`<div class="tactical-modes">${[['walk','Шаг'],['run','Бег'],['jump','Прыжок']].map(([key,name])=>`<button data-tactical="mode" data-mode="${key}" aria-pressed="${tacticalMode===key}" ${tacticalPending?'disabled':''}>${name}</button>`).join('')}</div><div class="tactical-unit-actions"><button data-tactical="action" data-action="stand" ${u.ap<4||tacticalPending?'disabled':''}>Встать · 4 ОД</button><button data-tactical="action" data-action="prone" ${u.ap<1||tacticalPending?'disabled':''}>Лечь · 1 ОД</button></div>`:''}<div class="tactical-attacks">${u.attacks.map((base,i)=>{const a=TacticalBattle.combat.attackValues(u,base,b);return `<button data-tactical="select-attack" data-attack="${i}" ${!turn||u.ap<a.cost||tacticalPending?'disabled':''} aria-pressed="${tacticalMode==='attack'&&tacticalAttack===i}"><b>${esc(a.name)}</b><strong>${a.chance}%</strong><span>${esc(a.damage)} · ${a.cost} ОД · ББ ${a.bb} · ${a.range} кл.</span>${a.ammo!==null?`<small>Боезапас ${a.ammo} · расход ${a.ammoCost}</small>`:''}</button>`;}).join('')||'<p class="muted">Нет настроенных атак.</p>'}</div>${renderTacticalMoves(u,turn)}<div class="tactical-combat-state">${u.opportunityMax?`<p>Атаки по возможности: <b>${u.opportunityLeft} / ${u.opportunityMax}</b></p>`:''}${u.stance?`<p>${esc(u.stance.name)} · до раунда ${u.stance.until}</p>`:''}${u.stunnedUntil>b.round?`<p>Оглушён до раунда ${u.stunnedUntil}</p>`:''}${u.dead?'<p>Мёртв</p>':u.dying?'<p>При смерти</p>':u.unconscious?'<p>Без сознания</p>':''}${u.traumas?.length?`<details><summary>Травмы (${u.traumas.length})</summary>${u.traumas.map(t=>`<p>${esc(t)}</p>`).join('')}</details>`:''}</div>${tacticalOwner()?`<button data-tactical="hp" data-unit="${u.id}">Изменить HP</button>`:''}`;
}
function renderTacticalPage(){
 if(!tacticalState)return renderTacticalEntry();const b=tacticalState,active=TacticalBattle.activeTeam(b),hostOnline=tacticalDemo||Date.now()-(tacticalRoom?.hostSeenAt?.toMillis?.()||0)<45000;
 return `<section class="tactical-header"><div><div class="tag">${tacticalDemo?'ЛОКАЛЬНЫЙ ТЕСТ / ВСЕ КОМАНДЫ':'ОНЛАЙН / '+tacticalCode}</div><h1>${esc(b.map.name)}</h1><p>${b.phase==='lobby'?'Расстановка команд':b.phase==='paused'?'Пауза':b.phase==='finished'?'Бой завершён':'Раунд '+b.round+' · ход «'+esc(active?.name||'—')+'»'}</p></div><div class="tactical-toolbar">${tacticalDemo&&b.phase==='lobby'?'<button class="primary-action" data-tactical="start">Начать бой</button>':''}${tacticalDemo&&tacticalLocalSetup?'<button data-tactical="reset-local">Заново</button>':''}${!tacticalDemo?'<button data-tactical="invite">Скопировать приглашение</button>':''}<button data-tactical="help" aria-label="Правила тактического боя">i</button><button data-tactical="leave">Выйти из комнаты</button></div></section><p class="tactical-status ${!hostOnline?'cloud-error':''}" data-tactical-status role="status">${esc(!hostOnline?'Ведущий не в сети. Действия ждут его возвращения.':tacticalStatus||'Подключено')}</p><div class="tactical-team-strip">${b.teams.map(t=>`<div class="tactical-team-chip ${active?.id===t.id&&b.phase==='battle'?'active':''}" style="--team-color:${t.color}"><b>${esc(t.name)}</b><small>${tacticalDemo?'Ручное управление · ':t.ownerUid===tacticalSelf()?'Ваша команда · ':''}${b.units.filter(u=>u.teamId===t.id&&u.hp>0).length} / ${b.units.filter(u=>u.teamId===t.id).length} бойцов</small></div>`).join('')}</div>${renderTacticalReactions()}<div class="tactical-layout"><section class="battle-card tactical-map-card"><div class="tactical-map-toolbar"><span>1 клетка · ${tacticalMode==='attack'?'выберите цель':tacticalBrush?'рисование карты':'выберите клетку'}</span><button data-tactical="zoom" data-delta="-6" aria-label="Уменьшить карту">−</button><button data-tactical="zoom" data-delta="6" aria-label="Увеличить карту">+</button></div>${renderTacticalMap()}<div class="tactical-legend"><span>▰ Стена</span><span>≈ Трудно · ×2</span><span>▱ Укрытие · −20%</span></div>${tacticalOwner()&&b.phase==='lobby'?`<details><summary>Локация и редактирование карты</summary><select id="tactical-location" aria-label="Локация боя">${tacticalLocationOptions(b.map.key)}</select><div class="tactical-modes">${[['','Расстановка'],['.','Пол'],['#','Стена'],['~','Трудно'],['c','Укрытие']].map(([value,label])=>`<button data-tactical="brush" data-brush="${value}" aria-pressed="${tacticalBrush===value}">${label}</button>`).join('')}</div></details>`:''}</section><aside class="battle-card tactical-inspector">${renderTacticalUnit()}${b.phase==='battle'&&(tacticalOwner()||active?.ownerUid===tacticalSelf())?`<button class="primary-action tactical-end-turn" data-tactical="end-turn" ${tacticalPending||b.pendingMove?'disabled':''}>Завершить ход команды →</button>`:''}</aside></div><div class="tactical-bottom"><section class="battle-card"><div class="section-heading"><h2>Составы команд</h2>${b.phase==='lobby'?'<button data-tactical="add-unit">+ Боец</button>':''}${tacticalOwner()&&b.phase==='lobby'?'<button data-tactical="add-team">+ NPC-команда</button>':''}</div>${b.teams.map(t=>`<div class="tactical-roster-team"><h3 style="color:${t.color}">${esc(t.name)}</h3>${b.units.filter(u=>u.teamId===t.id).map(u=>`<button data-tactical="unit" data-unit="${u.id}" aria-pressed="${u.id===tacticalSelected}"><span>${esc(u.name)}</span><small>${u.hp} HP · ${u.ap} ОД</small></button>`).join('')||'<small class="muted">Пока нет бойцов</small>'}</div>`).join('')}${!tacticalDemo?`<small class="muted">Подключено игроков: ${tacticalMembers.length}. Ведущий держит комнату открытой.</small>`:''}<div class="tactical-host-actions">${tacticalOwner()&&b.phase==='lobby'?'<button class="primary-action" data-tactical="start">Начать бой</button>':''}${tacticalOwner()&&['battle','paused'].includes(b.phase)?`<button data-tactical="pause">${b.phase==='paused'?'Продолжить':'Пауза'}</button>`:''}${tacticalOwner()&&b.history.length?'<button data-tactical="undo">↶ Отменить последнее действие</button>':''}</div></section><section class="battle-card tactical-log"><h2>Журнал сражения</h2>${b.log.map(message=>`<p>${esc(message)}</p>`).join('')||'<p class="muted">Пригласите игроков и расставьте команды.</p>'}</section></div>`;
}
function tacticalUnitFields(){const u=tacticalUnitDraft;return `<details class="tactical-draft-sprite"><summary>Спрайт · ${esc(TacticalBattle.sprites.find(s=>s.id===u.spriteId)?.name||'Инициалы')}</summary>${tacticalSpritePicker(u.spriteId,'draft-sprite')}</details><div class="fields">${[['name','Имя','text'],['hpMax','Макс. HP','number'],['hp','Текущие HP','number'],['apMax','ОД / раунд','number'],['reaction','Реакция','number'],['armor','Броня AR','number'],['dodge','Уворот, %','number'],['shock','Стойкость, %','number'],['opportunityMax','Заряды атаки по возможности','number'],['walk','Шаг, клеток / ОД','number'],['run','Бег, клеток / ОД','number'],['jump','Прыжок, клеток','number'],['jumpCost','Прыжок, ОД','number']].map(([key,label,type])=>`<label>${label}<input data-battle-unit="${key}" type="${type}" value="${esc(u[key])}" ${type==='number'?'min="0" step="any"':'maxlength="80"'}></label>`).join('')}</div><div class="fields">${['STR','DEX','CON','RTC','ACC','INT','LCK'].map(k=>`<label>${k}<input type="number" min="0" step="1" data-battle-stat="${k}" value="${u.stats?.[k]||0}"></label>`).join('')}</div><div class="section-heading"><h3>Атаки</h3><button data-tactical="draft-attack">+ Атака</button></div><div class="tactical-attack-editors">${u.attacks.map((a,i)=>`<details data-attack-row="${i}" open><summary>${esc(a.name)}</summary><div class="fields">${[['name','Название','text'],['damage','Урон, например 1d100 + 20','text'],['cost','Стоимость ОД','number'],['chance','Шанс, %','number'],['bb','ББ','number'],['range','Дальность, клеток','number'],['ammo','Боезапас (пусто — без боезапаса)','number'],['ammoCost','Расход за атаку','number'],['level','Уровень навыка оружия','number'],['baseStat','Основной стат атаки','number'],['criticalChance','Критический шанс, %','number'],['criticalPower','Бонус показателя крита','number'],['criticalMultiplier','Бонус множителя крита','number']].map(([key,label,type])=>`<label>${label}<input data-battle-attack="${key}" type="${type}" value="${esc(a[key]??'')}" ${type==='number'?'step="any"':'maxlength="120"'}></label>`).join('')}</div><label class="check-row"><input type="checkbox" data-battle-attack="melee" ${a.melee?'checked':''}>Оружие ближнего боя</label><button data-tactical="draft-remove-attack" data-index="${i}">Убрать атаку</button></details>`).join('')}</div>`;}
function tacticalReadDraft(){const dialog=document.querySelector('#tactical-dialog');tacticalUnitDraft.stats??={};for(const input of dialog.querySelectorAll('[data-battle-stat]'))tacticalUnitDraft.stats[input.dataset.battleStat]=Number(input.value);for(const input of dialog.querySelectorAll('[data-battle-unit]'))tacticalUnitDraft[input.dataset.battleUnit]=input.type==='number'?Number(input.value):input.value;tacticalUnitDraft.attacks=[...dialog.querySelectorAll('[data-attack-row]')].map(row=>({...tacticalUnitDraft.attacks[Number(row.dataset.attackRow)],...Object.fromEntries([...row.querySelectorAll('[data-battle-attack]')].map(input=>[input.dataset.battleAttack,input.dataset.battleAttack==='ammo'&&input.value===''?null:input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value]))}));}
function renderTacticalDialog(){if(!tacticalDialog)return '';let title='',body='',action='';const d=tacticalDialog;
 if(d.kind==='move-skill'||d.kind==='move-info'){
  const u=tacticalState.units.find(u=>u.id===d.unitId),m=u.moves[d.moveIndex],weapon=u.attacks[m.attackIndex],a=TacticalBattle.combat.attackValues(u,weapon,tacticalState,m),entry=RULE_ENTRIES.find(e=>e.category==='Приёмы'&&e.title===m.name);
  title=m.name;body=`<p>${esc(weapon.name)} · ${a.cost??'цена мастера'} ОД · ${a.chance===null?'шанс по эффектам':a.chance+'%'} · радиус ${weapon.range}</p><p>Защита цели: ${esc(m.defense||'—')}</p><p class="tactical-move-description">${esc(entry?.text||'')}</p>${m.blocked?`<p class="formula-error">Требования: ${esc(m.blocked)}</p>${tacticalOwner()?'<label class="check-row"><input type="checkbox" id="tactical-move-override">Разрешение ведущего обойти требования</label>':''}`:''}`;
  if(d.kind==='move-skill'){
   if(!/стойка$/.test(m.name)){
    const multi=['Двойной удар','Круговой удар','Комбинация'].includes(m.name),targets=tacticalState.units.filter(t=>t.teamId!==u.teamId&&t.hp>0&&TacticalBattle.distance(u,t)<=weapon.range&&TacticalBattle.lineOfSight(tacticalState,u,t));
    body+=multi?`<fieldset class="tactical-target-select"><legend>Цели в радиусе оружия</legend>${targets.map(t=>`<label class="check-row"><input type="checkbox" value="${t.id}" ${t.id===d.targetId?'checked':''}>${esc(t.name)}</label>`).join('')}</fieldset>`:`<p>Цель: <b>${esc(tacticalState.units.find(t=>t.id===d.targetId)?.name||'—')}</b></p>`;
    if(m.name==='Комбинация'){const choices=u.moves.map((e,i)=>({e,i})).filter(({e})=>e.attackIndex===m.attackIndex&&e.name!=='Комбинация'&&!/стойка$/.test(e.name));const options=choices.map(({e,i})=>`<option value="${i}">${esc(e.name)}</option>`).join('');body+=`<label>Первый приём<select id="tactical-combo-first">${options}</select></label><label>Второй приём<select id="tactical-combo-second">${options}</select></label><label>ОД комбинации, согласованные с ведущим<input type="number" id="tactical-combo-cost" min="0" max="100" required></label>`;}
   }else body+='<p>Длительность будет определена броском d6. Одновременно действует одна стойка.</p>';
   action='confirm-skill';
  }
 }
 if(d.kind==='unit'){title='Добавить бойца';body=`<label>Команда<select id="tactical-unit-team">${tacticalState.teams.filter(t=>tacticalOwner()||t.ownerUid===tacticalSelf()).map(t=>`<option value="${t.id}" ${t.id===d.teamId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Из своей библиотеки<select id="tactical-unit-source"><option value="">Собственный боец / NPC</option>${characterRecords.filter(r=>!r.deletedAt).map(r=>`<option value="${r.id}" ${tacticalUnitDraft.sourceId===r.id?'selected':''}>${esc(r.data.info.name)}</option>`).join('')}</select></label><div id="tactical-unit-fields">${tacticalUnitFields()}</div>`;action='save-unit';}
 if(d.kind==='team'){title='NPC-команда';body='<label>Название<input id="tactical-npc-team" maxlength="50" value="Противники"></label>';action='save-team';}
 if(d.kind==='hp'){const u=tacticalState.units.find(u=>u.id===d.unitId);title='HP · '+u.name;body=`<label>Текущие HP<input id="tactical-hp" type="number" min="0" max="${u.hpMax}" value="${u.hp}"></label>`;action='save-hp';}
 if(d.kind==='move'){title='Перемещение';body=`<p>${esc(d.unitName)} → ${d.x+1}:${d.y+1}</p><p>Стоимость: <b>${d.cost} ОД</b>.</p>`;action='confirm-move';}
 if(d.kind==='attack'){title='Подтвердить атаку';body=`<p>${esc(d.unitName)} → ${esc(d.targetName)}</p><p>${esc(d.attack.name)} · ${d.attack.cost} ОД · ${d.attack.chance}% до укрытия</p><p>${esc(d.attack.damage)} · ББ ${d.attack.bb}</p>`;action='confirm-attack';}
 if(d.kind==='sprite'){const id=d.sheet?state.info.tacticalSprite:tacticalState.units.find(u=>u.id===d.unitId)?.spriteId;title=d.sheet?'Спрайт персонажа':'Спрайт бойца';body=tacticalSpritePicker(id)+`<p class="help-copy">${d.sheet?'Выбор сохраняется с персонажем.':'Изменяется только боевая копия; лист персонажа сохраняет свой спрайт.'}</p>`+'<p class="help-copy">Внешний вид не меняет характеристики. Исходное направление — юг (вниз). Поворот на карте не расходует ОД.</p>';}
 if(d.kind==='help'){title='Правила тактического боя';body=tacticalHelp();}
 return `<dialog id="tactical-dialog" class="formula-dialog" aria-labelledby="tactical-dialog-title"><div class="toolbar"><h2 id="tactical-dialog-title">${esc(title)}</h2><button data-tactical="close-dialog" aria-label="Закрыть окно боя">×</button></div>${body}<p id="tactical-dialog-error" class="formula-error" role="status"></p>${action?`<div class="dialog-actions"><button data-tactical="close-dialog">Отмена</button><button data-tactical="${action}">Подтвердить</button></div>`:''}</dialog>`;
}
function tacticalOpenDialog(d){tacticalDialog=d;document.querySelector('#tactical-dialog')?.remove();document.querySelector('#view').insertAdjacentHTML('beforeend',renderTacticalDialog());document.querySelector('#tactical-dialog').showModal();}
function tacticalCloseDialog(){tacticalDialog=null;document.querySelector('#tactical-dialog')?.remove();}
const beforeTacticalRender=render;
render=function(){
 if(tacticalUid!==cloudUser?.uid){tacticalDisconnect();tacticalUid=cloudUser?.uid;tacticalDialog=null;tacticalAutoUid=null;}
 beforeTacticalRender();if(!libraryHome&&page!==9){const intro=document.querySelector('.intro');if(intro&&!intro.querySelector('[data-tactical="sheet-sprite"]'))intro.insertAdjacentHTML('beforeend',`<button class="character-sprite-button" data-tactical="sheet-sprite" aria-label="Изменить спрайт персонажа">${tacticalSpriteMarkup(state.info.tacticalSprite)||'<span aria-hidden="true">♟</span>'}<small>Спрайт</small></button>`);}document.body.classList.toggle('tactical-page',page===9&&!libraryHome);
 if(libraryHome){document.querySelector('.library-heading .play-shortcuts')?.insertAdjacentHTML('beforeend','<button data-tactical="open">Тактический бой</button>');if(tacticalInvitation)document.querySelector('.library-heading')?.insertAdjacentHTML('afterend',`<section class="cloud-panel"><div><b>Приглашение в бой · ${esc(tacticalInvitation)}</b><p>Войдите через Google, чтобы управлять своей командой.</p></div><button data-tactical="open">Открыть бой</button></section>`);}
 if(!libraryHome&&(page===9||tacticalDialog?.sheet)){if(tacticalDialog){document.querySelector('#view').insertAdjacentHTML('beforeend',renderTacticalDialog());document.querySelector('#tactical-dialog').showModal();}}
 if(cloudUser&&tacticalInvitation&&tacticalAutoUid!==cloudUser.uid){const invitationUid=cloudUser.uid;tacticalAutoUid=invitationUid;setTimeout(()=>{if(cloudUser?.uid!==invitationUid||tacticalAutoUid!==invitationUid)return;libraryHome=false;page=9;render();tacticalConnect(false).catch(error=>toast(error.message));},0);}
};
document.addEventListener('cancel',event=>{if(event.target.id==='tactical-dialog')tacticalCloseDialog();},true);
document.addEventListener('change',event=>{
 if(event.target.closest('.tactical-entry')){event.stopImmediatePropagation();return;}
 if(event.target.id==='tactical-location'){event.stopImmediatePropagation();tacticalSend('location',{key:event.target.value}).catch(error=>toast(error.message));}
 if(event.target.id==='tactical-unit-source'){event.stopImmediatePropagation();try{const record=characterRecords.find(r=>r.id===event.target.value);tacticalUnitDraft=record?tacticalSnapshot(record):tacticalDefaultUnit();document.querySelector('#tactical-unit-fields').innerHTML=tacticalUnitFields();}catch(error){document.querySelector('#tactical-dialog-error').textContent=error.message;}}
 if(event.target.closest('#tactical-dialog'))event.stopImmediatePropagation();
},true);
document.addEventListener('click',async event=>{
 if(event.target.closest('.tactical-entry label,#tactical-dialog label')){event.stopImmediatePropagation();return;}
 const nav=event.target.closest('[data-page]');if(nav&&page===9&&!activeCharacterId&&+nav.dataset.page!==9){event.stopImmediatePropagation();libraryHome=true;page=0;render();return;}
 const button=event.target.closest('[data-tactical]');if(!button){if(event.target.closest('.tactical-entry,#tactical-dialog'))event.stopImmediatePropagation();return;}event.stopImmediatePropagation();const d=button.dataset,u=tacticalState?.units.find(u=>u.id===tacticalSelected);
 try{switch(d.tactical){
  case 'refresh-sheet':{const unit=tacticalState.units.find(u=>u.id===d.unit),record=characterRecords.find(r=>r.id===unit.sourceId&&!r.deletedAt);if(!record)throw Error('Исходный лист недоступен.');const fresh=tacticalSnapshot(record.id===activeCharacterId?{...record,data:structuredClone(state)}:record);await tacticalSend('action',{action:'refreshSheet',unitId:unit.id,unit:fresh});return;}
  case 'sheet-sprite':tacticalOpenDialog({kind:'sprite',sheet:true});return;
  case 'unit-sprite':tacticalOpenDialog({kind:'sprite',unitId:d.unit});return;
  case 'pick-sprite':{const id=d.sprite||null;if(id&&!TacticalBattle.sprites.some(s=>s.id===id))throw Error('Неизвестный спрайт.');const p=tacticalDialog;tacticalCloseDialog();if(p.sheet){state.info.tacticalSprite=id;save();render();}else{const unit=tacticalState.units.find(u=>u.id===p.unitId);await tacticalSend('action',{unitId:unit.id,action:'appearance',spriteId:id,facing:unit.facing??0});}return;}
  case 'draft-sprite':tacticalReadDraft();tacticalUnitDraft.spriteId=d.sprite||null;document.querySelector('#tactical-unit-fields').innerHTML=tacticalUnitFields();return;
  case 'face':await tacticalSend('action',{unitId:u.id,action:'appearance',spriteId:u.spriteId??null,facing:((u.facing??0)+Number(d.delta)+8)%8});return;
  case 'open':libraryHome=false;page=9;render();return;
  case 'create':await tacticalConnect(true);return;
  case 'join':await tacticalConnect(false);return;
  case 'demo':tacticalDemoBattle();return;
  case 'solo':tacticalSoloBattle(document.querySelector('#tactical-solo-character').value,document.querySelector('#tactical-solo-map').value,Number(document.querySelector('#tactical-solo-enemies').value));return;
  case 'reset-local':tacticalResetLocal();return;
  case 'leave':tacticalDisconnect();tacticalStatus='';tacticalRefresh();return;
  case 'invite':{const url=new URL(location.href);url.search='';url.searchParams.set('battle',tacticalCode);await navigator.clipboard.writeText(url.href);toast('Приглашение скопировано · '+tacticalCode);return;}
  case 'help':tacticalOpenDialog({kind:'help'});return;
  case 'close-dialog':tacticalCloseDialog();tacticalRefresh();return;
  case 'zoom':tacticalZoom=Math.max(26,Math.min(66,tacticalZoom+ +d.delta));tacticalRefresh();return;
  case 'unit':tacticalSelected=d.unit;tacticalSelectedMove=null;tacticalMode='walk';tacticalRefresh();return;
  case 'mode':tacticalSelectedMove=null;tacticalMode=d.mode;tacticalBrush='';tacticalRefresh();return;
  case 'brush':tacticalBrush=d.brush;tacticalRefresh();return;
  case 'cell':{
   const x=+d.x,y=+d.y,target=tacticalState.units.find(u=>u.x===x&&u.y===y);
   if(tacticalBrush){await tacticalSend('terrain',{x,y,tile:tacticalBrush});return;}
   if(tacticalMode==='attack'&&u&&target&&target.teamId!==u.teamId){if(tacticalSelectedMove!==null){tacticalOpenDialog({kind:'move-skill',unitId:u.id,moveIndex:tacticalSelectedMove,targetId:target.id});return;}if(TacticalBattle.distance(u,target)>u.attacks[tacticalAttack].range)throw Error('Цель вне дальности.');if(!TacticalBattle.lineOfSight(tacticalState,u,target))throw Error('Линия огня перекрыта.');tacticalOpenDialog({kind:'attack',unitName:u.name,targetName:target.name,unitId:u.id,targetId:target.id,attackIndex:tacticalAttack,attack:u.attacks[tacticalAttack]});return;}
   if(target){tacticalSelected=target.id;tacticalMode='walk';tacticalRefresh();return;}
   if(!u||!tacticalCanControl(u))throw Error('Выберите бойца своей команды.');
   if(tacticalState.phase==='lobby'){await tacticalSend('deploy',{unitId:u.id,x,y});return;}
   const move=TacticalBattle.movement(tacticalState,u,x,y,tacticalMode);if(move.cost>u.ap)throw Error('Недостаточно ОД.');tacticalOpenDialog({kind:'move',unitId:u.id,unitName:u.name,x,y,cost:move.cost,mode:tacticalMode});return;
  }
  case 'confirm-move':{const p=tacticalDialog;tacticalCloseDialog();await tacticalSend('move',{unitId:p.unitId,x:p.x,y:p.y,mode:p.mode});return;}
  case 'select-attack':tacticalSelectedMove=null;tacticalAttack=+d.attack;tacticalMode='attack';tacticalBrush='';tacticalRefresh();return;
  case 'confirm-attack':{const p=tacticalDialog;tacticalCloseDialog();await tacticalSend('attack',{unitId:p.unitId,targetId:p.targetId,attackIndex:p.attackIndex});return;}
  case 'opportunity':await tacticalSend('action',{action:'opportunity',reactionId:d.reaction});return;
  case 'skip-opportunity':await tacticalSend('action',{action:'skipOpportunity',reactionId:d.reaction});return;
  case 'move-info':tacticalOpenDialog({kind:'move-info',unitId:u.id,moveIndex:+d.move});return;
  case 'select-move':{tacticalSelectedMove=+d.move;const m=u.moves[tacticalSelectedMove];tacticalAttack=m.attackIndex;if(/стойка$/.test(m.name))tacticalOpenDialog({kind:'move-skill',unitId:u.id,moveIndex:tacticalSelectedMove});else{tacticalMode='attack';tacticalRefresh();}return;}
  case 'confirm-skill':{const p=tacticalDialog,targets=[...document.querySelectorAll('.tactical-target-select input:checked')].map(e=>e.value),combo=[document.querySelector('#tactical-combo-first')?.value,document.querySelector('#tactical-combo-second')?.value].map(Number),cost=Number(document.querySelector('#tactical-combo-cost')?.value),override=!!document.querySelector('#tactical-move-override')?.checked;tacticalCloseDialog();await tacticalSend('action',{action:'moveSkill',unitId:p.unitId,moveIndex:p.moveIndex,targetIds:targets.length?targets:p.targetId?[p.targetId]:[],combo,comboCost:cost,override});tacticalSelectedMove=null;return;}
  case 'action':await tacticalSend('action',{unitId:u.id,action:d.action});return;
  case 'end-turn':await tacticalSend('endTurn');return;
  case 'start':await tacticalSend('start');return;
  case 'pause':await tacticalSend('pause');return;
  case 'undo':await tacticalSend('undo');return;
  case 'remove-unit':await tacticalSend('removeUnit',{unitId:d.unit});return;
  case 'add-team':tacticalOpenDialog({kind:'team'});return;
  case 'save-team':{const name=document.querySelector('#tactical-npc-team').value;tacticalCloseDialog();await tacticalSend('team',{name});return;}
  case 'hp':tacticalOpenDialog({kind:'hp',unitId:d.unit});return;
  case 'save-hp':{const id=tacticalDialog.unitId,value=Number(document.querySelector('#tactical-hp').value);tacticalCloseDialog();await tacticalSend('hp',{unitId:id,value});return;}
  case 'add-unit':{const team=tacticalTeam()||(tacticalOwner()?tacticalState.teams[0]:null);if(!team)throw Error('Дождитесь, пока ведущий добавит вашу команду.');const record=characterRecords.find(r=>r.id===activeCharacterId)||characterRecords.find(r=>!r.deletedAt);tacticalUnitDraft=record?tacticalSnapshot(record):tacticalDefaultUnit();tacticalOpenDialog({kind:'unit',teamId:team.id});return;}
  case 'draft-attack':tacticalReadDraft();if(tacticalUnitDraft.attacks.length>=8)throw Error('Максимум 8 атак.');tacticalUnitDraft.attacks.push({...tacticalDefaultUnit().attacks[0]});document.querySelector('#tactical-unit-fields').innerHTML=tacticalUnitFields();return;
  case 'draft-remove-attack':tacticalReadDraft();tacticalUnitDraft.attacks.splice(+d.index,1);document.querySelector('#tactical-unit-fields').innerHTML=tacticalUnitFields();return;
  case 'save-unit':{tacticalReadDraft();const unit=TacticalBattle.sanitizeUnit(tacticalUnitDraft);for(const a of unit.attacks)TacticalBattle.dice(a.damage,()=>0);const teamId=document.querySelector('#tactical-unit-team').value;tacticalCloseDialog();await tacticalSend('addUnit',{teamId,unit});return;}
 }}catch(error){const field=document.querySelector('#tactical-dialog-error');if(field)field.textContent=error.message;else{tacticalReport(error.message,true);toast(error.message);}}
},true);
render();
